from dataclasses import dataclass

from app.models.task_template import TaskSource
from app.models.test import Level


@dataclass(frozen=True)
class CatalogTask:
    source: TaskSource
    level: Level
    slug: str
    title: str
    statement: str
    tags: tuple[str, ...]
    tests: tuple[tuple[str, str], ...]


def group(
    source: TaskSource,
    level: Level,
    rows: list[tuple[str, str, str, tuple[str, ...], tuple[tuple[str, str], ...]]],
) -> list[CatalogTask]:
    return [CatalogTask(source, level, *row) for row in rows]


